import torch
from torch.utils.cpp_extension import load_inline

# CUDA source implementing half‑precision GEMM
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#define TILE_M 16
#define TILE_N 16
#define TILE_K 16

__global__ void matmul_kernel(const __half* __restrict__ A,
                              const __half* __restrict__ B,
                              __half* __restrict__ C,
                              int M, int K, int N) {
    int blockRow = blockIdx.y;
    int blockCol = blockIdx.x;
    int threadRow = threadIdx.y;
    int threadCol = threadIdx.x;

    int row = blockRow * TILE_M + threadRow;
    int col = blockCol * TILE_N + threadCol;

    float acc = 0.0f;

    __shared__ __half As[TILE_M][TILE_K];
    __shared__ __half Bs[TILE_K][TILE_N];

    int tiles = (K + TILE_K - 1) / TILE_K;
    for (int t = 0; t < tiles; ++t) {
        int aRow = row;
        int aCol = t * TILE_K + threadCol;
        As[threadRow][threadCol] = (aRow < M && aCol < K)
            ? A[aRow * K + aCol]
            : __float2half(0.0f);

        int bRow = t * TILE_K + threadRow;
        int bCol = col;
        Bs[threadRow][threadCol] = (bRow < K && bCol < N)
            ? B[bRow * N + bCol]
            : __float2half(0.0f);

        __syncthreads();

        #pragma unroll
        for (int k = 0; k < TILE_K; ++k) {
            acc += __half2float(As[threadRow][k]) * __half2float(Bs[k][threadCol]);
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        C[row * N + col] = __float2half(acc);
    }
}

torch::Tensor matmul_fp16(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dtype() == torch::kHalf && B.dtype() == torch::kHalf,
                "Only half precision supported");
    TORCH_CHECK(A.is_cuda() && B.is_cuda(),
                "Inputs must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2,
                "Inputs must be 2‑D matrices");
    TORCH_CHECK(A.size(1) == B.size(0),
                "Inner dimensions must match");

    int64_t M = A.size(0);
    int64_t K = A.size(1);
    int64_t N = B.size(1);

    auto options = torch::TensorOptions()
                       .dtype(torch::kHalf)
                       .device(A.device())
                       .layout(torch::kStrided);
    torch::Tensor C = torch::empty({M, N}, options);

    const dim3 block(TILE_N, TILE_M);
    const dim3 grid((N + TILE_N - 1) / TILE_N,
                    (M + TILE_M - 1) / TILE_M);

    const __half* A_ptr = reinterpret_cast<const __half*>(A.data_ptr());
    const __half* B_ptr = reinterpret_cast<const __half*>(B.data_ptr());
    __half* C_ptr = reinterpret_cast<__half*>(C.data_ptr());

    AT_CUDA_CHECK(cudaGetLastError());
    matmul_kernel<<<grid, block>>>(
        A_ptr, B_ptr, C_ptr,
        static_cast<int>(M),
        static_cast<int>(K),
        static_cast<int>(N));
    AT_CUDA_CHECK(cudaGetLastError());

    return C;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matmul_fp16", &matmul_fp16, "Half‑precision GEMM (CUDA)");
}
'''

# Compile the inline extension
_matmul_ext = load_inline(name='matmul_fp16_ext',
                         cpp_sources='',
                         cuda_sources=cuda_source,
                         functions=['matmul_fp16'],
                         verbose=False)

class ModelNew(torch.nn.Module):
    """Drop‑in replacement for the reference Model using a custom CUDA kernel."""
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # Ensure inputs are half‑precision CUDA tensors
        A_h = A.to(dtype=torch.float16, device='cuda')
        B_h = B.to(dtype=torch.float16, device='cuda')
        return _matmul_ext.matmul_fp16(A_h, B_h)
